"use client";

import * as React from "react";
import { useAtlasMember } from "@/components/glass-atlas";
import { LiquidGlass } from "@/components/liquid-glass";
import {
  resolveGlassStyle,
  type GlassKind,
  type GlassMode,
  type GlassSurface,
} from "@/lib/glass-theme";
import { useGlassTheme } from "@/components/glass/glass-theme-provider";
import { cn } from "@/lib/utils";
import { useAdaptiveContrast } from "@/components/adaptive-contrast";
import { sampleFromLuminance } from "@/lib/contrast";
import { useGlassScene, useGlassSettings } from "@/components/glass-scene";

const GlassSurfaceContext = React.createContext<{ lightInk: boolean } | null>(
  null,
);
export function useWithinGlassSurface() {
  return Boolean(React.useContext(GlassSurfaceContext));
}
/** Foreground context for custom low-level LiquidGlass compositions. Adds no DOM or optics. */
export function GlassContent({
  ink,
  children,
}: {
  ink: "light" | "dark";
  children: React.ReactNode;
}) {
  return (
    <GlassSurfaceContext.Provider value={{ lightInk: ink === "light" }}>
      {children}
    </GlassSurfaceContext.Provider>
  );
}

export interface GlassSurfaceProps extends Omit<
  React.HTMLAttributes<HTMLElement>,
  "children"
> {
  kind?: GlassKind;
  /** Automatic background sampling, or an explicit text color. */
  ink?: "auto" | "light" | "dark";
  /** Add only the neutral overlay needed by the sampled background. */
  contrastProtection?: boolean;
  /** Compose onto one shadcn/Radix component that forwards props and ref. */
  asChild?: boolean;
  surface?: GlassSurface;
  mode?: GlassMode;
  radius?: number;
  shape?: import("@/lib/glass").GlassShape;
  /** Classify a bounded scene on paints; explicit local blur remains authoritative. */
  adaptiveBackdrop?: boolean;
  config?: Partial<import("@/lib/glass").LensParams>;
  deformation?: { x: number; y: number };
  sceneRef?: React.RefObject<HTMLElement | null>;
  frameRate?: number;
  /** Share optics or admit this surface to the document budget. */
  rendering?: "auto" | "shared";
  /** Disable atlas batching when the surface needs its own transform. */
  composite?: boolean;
  /** Higher values are admitted first; overlays use 10. The device cap still applies. */
  priority?: number;
  tintBlendMode?: React.CSSProperties["mixBlendMode"];
  as?: "div" | "section" | "aside" | "nav" | "header" | "footer" | "article";
  /** @deprecated Surfaces use optical edges without elevation. */
  shadow?: boolean;
  children?: React.ReactNode;
  ref?: React.Ref<HTMLElement>;
}

/**
 * The one component every glass UI part is built on. Resolves the material
 * for a component family (kind), honoring explicit overrides, the global
 * per-kind override map and the active light/dark mode.
 *
 * Children render directly into the glass root — layout classes (flex,
 * grid, p-*, gap-*) behave exactly like they would on a plain div.
 */
export function GlassSurface({
  kind = "card",
  ink: requestedInk,
  contrastProtection: requestedProtection,
  asChild = false,
  sceneRef,
  rendering = "auto",
  composite = true,
  priority,
  tintBlendMode,
  surface,
  mode,
  radius,
  shape: requestedShape,
  adaptiveBackdrop = true,
  config,
  deformation,
  as,
  shadow = false,
  className = "",
  children,
  ref,
  style: rootStyle,
  ...rest
}: GlassSurfaceProps) {
  const inheritedSurface = React.useContext(GlassSurfaceContext);
  // React context crosses portals; an overlay still needs its own optical layer.
  const overlay =
    /dialog|popover|tooltip|select|drawer|sheet|command|dropdown|context-menu|hover-card|toast/.test(
      kind,
    );
  const parentSurface = overlay ? null : inheritedSurface;
  const theme = useGlassTheme();
  const scene = useGlassScene();
  const settings = useGlassSettings();
  const ink = requestedInk ?? settings.ink ?? "auto";
  const contrastProtection =
    requestedProtection ?? settings.contrastProtection ?? true;
  const effectiveMode = mode ?? scene?.appearance ?? theme.resolvedMode;
  const effectiveSurface =
    surface ?? settings.surface ?? theme.surfaceFor(kind);
  const style = resolveGlassStyle({
    kind,
    surface: effectiveSurface,
    mode: effectiveMode,
    config: { ...settings.config, ...scene?.config, ...config },
    radius: radius ?? settings.radius,
  });
  const shape = requestedShape ?? (style.radius >= 999 ? "round" : "squircle");
  // A higher layer softens the text and controls it captures underneath it.
  // A local override remains useful for deliberately clear overlays.
  if (overlay && config?.blur === undefined) {
    style.params.blur = Math.max(
      style.params.blur,
      kind === "tooltip" ? 4 : /dialog|drawer|sheet|command/.test(kind) ? 8 : 6,
    );
  }
  const blend =
    tintBlendMode ?? (effectiveMode === "light" ? "normal" : "multiply");
  const localRef = React.useRef<HTMLElement | null>(null);
  const setRef = React.useCallback(
    (node: HTMLElement | null) => {
      localRef.current = node;
      if (typeof ref === "function") return ref(node);
      if (ref) ref.current = node;
    },
    [ref],
  );
  const compatibleConfig =
    !config ||
    Object.keys(config).every((key) => key === "tint" || key === "tintColor");
  const atlas = useAtlasMember(
    localRef,
    style.radius,
    composite &&
      !parentSurface &&
      !overlay &&
      rendering === "auto" &&
      compatibleConfig &&
      !deformation &&
      !sceneRef &&
      (effectiveSurface === undefined || effectiveSurface === "clear"),
    shape,
  );
  const sample = useAdaptiveContrast(localRef, {
    enabled:
      (ink === "auto" || settings.themeBehavior === "duotheme") &&
      !parentSurface,
    tone:
      settings.themeBehavior === "duotheme" && ink !== "auto" ? ink : undefined,
    source: sceneRef ?? scene?.source,
    live: scene?.live ?? false,
    interval: 300,
    tintColor: style.params.tintColor,
    tintOpacity: style.params.tint,
    tintBlendMode: blend,
    brightness: style.params.brightness,
    saturate: style.params.saturate,
    contrast: style.params.contrast,
    fallback: sampleFromLuminance(effectiveMode === "dark" ? 0.02 : 0.9, 0),
  });
  const tone =
    ink === "auto"
      ? (parentSurface?.lightInk ?? sample.tone === "light")
      : ink === "light";
  const foreground = tone ? "#ffffff" : "#000000";
  const background = tone ? "#151719" : "#ffffff";
  const colors = {
    "--glass-action": "#006de5",
    "--background": background,
    "--foreground": foreground,
    "--card": "transparent",
    "--card-foreground": foreground,
    "--muted": tone ? "#ffffff18" : "#0000000a",
    "--muted-foreground": foreground,
    "--popover": background,
    "--popover-foreground": foreground,
    "--primary": foreground,
    "--primary-foreground": background,
    "--secondary": tone ? "#ffffff18" : "#0000000a",
    "--secondary-foreground": foreground,
    "--accent": tone ? "#ffffff20" : "#0000000e",
    "--accent-foreground": foreground,
    "--input": tone ? "#ffffff45" : "#00000030",
    "--border": tone ? "#ffffff30" : "#00000020",
    "--ring": foreground,
    "--destructive": tone ? "#ffb4b4" : "#a10820",
    "--sidebar": "transparent",
    "--sidebar-foreground": foreground,
    "--sidebar-primary": foreground,
    "--sidebar-primary-foreground": background,
    "--sidebar-accent": tone ? "#ffffff20" : "#0000000e",
    "--sidebar-accent-foreground": foreground,
    "--sidebar-border": tone ? "#ffffff30" : "#00000020",
    "--sidebar-ring": foreground,
    colorScheme: tone ? "only dark" : "only light",
  };
  const protection =
    (ink === "auto" || settings.themeBehavior === "duotheme") &&
    contrastProtection &&
    !parentSurface
      ? sample.samples || sample.inherited
        ? (sample.scrimOpacity ?? 0)
        : 0.12
      : 0;

  return (
    <GlassSurfaceContext.Provider value={{ lightInk: tone }}>
      <LiquidGlass
        preset={effectiveSurface ?? "clear"}
        config={style.params}
        deformation={deformation}
        radius={style.radius}
        shape={shape}
        adaptiveBackdrop={adaptiveBackdrop}
        preserveBlur={
          overlay ||
          config?.blur !== undefined ||
          settings.config?.blur !== undefined ||
          scene?.config?.blur !== undefined ||
          effectiveSurface !== "clear"
        }
        tintBlendMode={blend}
        as={as}
        asChild={asChild}
        sceneRef={sceneRef}
        requireSceneCoverage={overlay}
        ref={setRef}
        readability={{
          color: tone ? "#000000" : "#ffffff",
          opacity: protection,
        }}
        rendering={
          atlas ? "composited" : parentSurface ? "inherited" : rendering
        }
        compositorReady={atlas?.active}
        priority={priority ?? (overlay ? 10 : 0)}
        data-adaptive-tone={tone ? "light" : "dark"}
        data-adaptive-source={
          sample.inherited
            ? "inherited"
            : sample.samples
              ? "sampled"
              : "fallback"
        }
        data-glass-compositor={atlas ? "atlas" : undefined}
        data-glass-await-optics={overlay && Boolean(scene) ? "true" : undefined}
        data-glass-appearance={effectiveMode}
        data-glass-theme-behavior={settings.themeBehavior ?? "unitheme"}
        data-glass-shape={shape}
        data-glass={kind}
        data-glass-surface={effectiveSurface ?? "default"}
        data-glass-mode={tone ? "dark" : "light"}
        style={{ ...colors, ...rootStyle } as React.CSSProperties}
        className={cn(
          "text-foreground",
          !parentSurface && "glass-material",
          shadow && "shadow-none",
          className,
        )}
        {...rest}
      >
        {children}
      </LiquidGlass>
    </GlassSurfaceContext.Provider>
  );
}

"use client";

import * as React from "react";
import { MonitorIcon, MoonIcon, SunIcon } from "lucide-react";
import { cn } from "@/lib/utils";
import {
  GLASS_KINDS,
  GLASS_SURFACES,
  SURFACE_LABELS,
  type GlassKind,
  type GlassSurface,
} from "@/lib/glass-theme";
import {
  useGlassTheme,
  type GlassModeSetting,
} from "@/components/glass/glass-theme-provider";

const MODE_OPTIONS: {
  value: GlassModeSetting;
  label: string;
  icon: React.ReactNode;
}[] = [
  { value: "light", label: "Light", icon: <SunIcon className="size-3.5" /> },
  { value: "dark", label: "Dark", icon: <MoonIcon className="size-3.5" /> },
  {
    value: "system",
    label: "System",
    icon: <MonitorIcon className="size-3.5" />,
  },
];

/**
 * Keyboard behaviour for a `role="radiogroup"`.
 *
 * ARIA requires a radio group to be a single tab stop whose arrow keys move
 * between radios — and, for a single-select group, moving focus also selects.
 * Without this every radio sits in the tab order and arrow keys do nothing, so
 * the control is unusable by keyboard.
 */
function useRadioGroupKeyboard(
  count: number,
  onSelect: (index: number) => void,
) {
  const [focused, setFocused] = React.useState(0);
  const refs = React.useRef<(HTMLButtonElement | null)[]>([]);

  const goTo = React.useCallback(
    (index: number) => {
      const next = ((index % count) + count) % count;
      setFocused(next);
      onSelect(next);
      refs.current[next]?.focus();
    },
    [count, onSelect],
  );

  const onKeyDown = React.useCallback(
    (event: React.KeyboardEvent<HTMLDivElement>) => {
      const deltas: Record<string, number> = {
        ArrowRight: 1,
        ArrowDown: 1,
        ArrowLeft: -1,
        ArrowUp: -1,
      };
      const delta = deltas[event.key];
      if (delta !== undefined) {
        event.preventDefault();
        goTo(focused + delta);
      } else if (event.key === "Home") {
        event.preventDefault();
        goTo(0);
      } else if (event.key === "End") {
        event.preventDefault();
        goTo(count - 1);
      }
    },
    [count, focused, goTo],
  );

  // Only the focused radio is reachable by Tab.
  const tabIndexFor = (index: number) => (index === focused ? 0 : -1);

  return { focused, setFocused, refs, onKeyDown, tabIndexFor };
}

export function GlassModeToggle({ className }: { className?: string }) {
  const { mode, setMode } = useGlassTheme();
  const select = React.useCallback(
    (index: number) => {
      const opt = MODE_OPTIONS[index];
      if (opt) setMode(opt.value);
    },
    [setMode],
  );
  const { setFocused, refs, onKeyDown, tabIndexFor } = useRadioGroupKeyboard(
    MODE_OPTIONS.length,
    select,
  );

  return (
    <div
      role="radiogroup"
      aria-label="Glass theme"
      onKeyDown={onKeyDown}
      className={cn(
        "glass-chip flex items-center gap-0.5 rounded-full p-0.5",
        className,
      )}
    >
      {MODE_OPTIONS.map((opt, index) => (
        <button
          key={opt.value}
          ref={(el) => {
            refs.current[index] = el;
          }}
          type="button"
          role="radio"
          aria-checked={mode === opt.value}
          // The label is hidden below `sm`, so the icon alone must not be the
          // accessible name.
          aria-label={opt.label}
          data-testid={`mode-${opt.value}`}
          tabIndex={tabIndexFor(index)}
          onFocus={() => setFocused(index)}
          onClick={() => setMode(opt.value)}
          className={cn(
            "flex cursor-pointer items-center gap-1.5 rounded-full px-2.5 py-1 text-[11px] font-semibold transition-colors",
            "focus-visible:ring-2 focus-visible:ring-ring/50 focus-visible:outline-none",
            mode === opt.value
              ? "bg-foreground text-background"
              : "text-muted-foreground hover:text-foreground",
          )}
        >
          {opt.icon}
          <span className="hidden sm:inline">{opt.label}</span>
        </button>
      ))}
    </div>
  );
}

export function SurfacePicker({
  kind,
  value,
  onValue,
  allowAuto = true,
  testIdPrefix,
  className,
}: {
  kind?: GlassKind;
  value?: GlassSurface | undefined;
  onValue: (surface: GlassSurface | null) => void;
  allowAuto?: boolean;
  testIdPrefix?: string;
  className?: string;
}) {
  const showAuto = allowAuto && !kind;
  const options = React.useMemo<(GlassSurface | null)[]>(
    () => [...(showAuto ? [null] : []), ...GLASS_SURFACES],
    [showAuto],
  );
  const select = React.useCallback(
    (index: number) => {
      const next = options[index];
      if (next !== undefined) onValue(next);
    },
    [onValue, options],
  );
  const { setFocused, refs, onKeyDown, tabIndexFor } = useRadioGroupKeyboard(
    options.length,
    select,
  );
  const label = (surface: GlassSurface | null) =>
    surface === null ? "Auto" : SURFACE_LABELS[surface];

  return (
    <div
      role="radiogroup"
      aria-label={kind ? `Surface for ${kind}` : "Global glass surface"}
      onKeyDown={onKeyDown}
      className={cn(
        "glass-chip flex flex-wrap items-center gap-0.5 rounded-full p-0.5",
        className,
      )}
    >
      {options.map((s, index) => {
        const isSelected = s === (value ?? null);
        return (
          <button
            key={s ?? "auto"}
            ref={(el) => {
              refs.current[index] = el;
            }}
            type="button"
            role="radio"
            aria-checked={isSelected}
            aria-label={label(s)}
            data-testid={`${testIdPrefix ?? "surface"}-${s ?? "auto"}`}
            tabIndex={tabIndexFor(index)}
            onFocus={() => setFocused(index)}
            onClick={() => onValue(s)}
            className={cn(
              "cursor-pointer rounded-full px-2.5 py-1 text-[11px] font-semibold transition-colors",
              "focus-visible:ring-2 focus-visible:ring-ring/50 focus-visible:outline-none",
              isSelected
                ? "bg-foreground text-background"
                : "text-muted-foreground hover:text-foreground",
            )}
          >
            {label(s)}
          </button>
        );
      })}
    </div>
  );
}

/** Global picker that re-pours every component family at once. */
export function GlobalSurfacePicker() {
  const { surfaces, setSurface, resetSurfaces } = useGlassTheme();
  const allSame = (() => {
    const values = Object.values(surfaces).filter(Boolean) as GlassSurface[];
    if (values.length === 0) return undefined;
    return values.every((v) => v === values[0])
      ? values[0]
      : ("mixed" as const);
  })();

  return (
    <div className="flex flex-wrap items-center gap-2">
      <SurfacePicker
        value={
          typeof allSame === "string" && allSame !== "mixed"
            ? allSame
            : undefined
        }
        onValue={(s) => {
          if (s === null) resetSurfaces();
          else for (const k of GLASS_KINDS) setSurface(k, s);
        }}
        testIdPrefix="global-surface"
      />
    </div>
  );
}

"use client";

import { useEffect, useLayoutEffect, useRef, useState, useSyncExternalStore, type ReactNode, type RefObject } from "react";
import { GlassLens } from "@/components/glass/glass-target-lens";
import { useGlassSettings } from "@/components/glass-scene";
import { CONTROL_LENS_PRESETS, buildControlLensTextures, controlLensMetrics, sampleControlLensSpring } from "@/lib/glass-lens-optics";
import { decodeLensTextures } from "@/lib/glass";
import { GlassFilterManager } from "@/lib/glass-filter";
import { GLASS_PRIORITY, registerGlassLens } from "@/lib/glass-performance";
import { subscribeReducedGlass as subscribe, prefersReducedGlass as reduced, serverGlassPreference as server } from "@/lib/glass-preferences";

const EMPTY = {
  left: 0,
  top: 0,
  width: 2,
  height: 2,
  x: 0,
  y: 0,
  visible: false,
  pointer: false,
  boundsWidth: 0,
  boundsHeight: 0,
};

/** The glass is the selected pill, including after its spring has settled. */
export function GlassSelection({
  children,
  refractionTarget,
}: {
  children: ReactNode;
  refractionTarget?: ReactNode;
  /** @deprecated Selection glass is now persistent. */
  opticalIdle?: boolean;
}) {
  const root = useRef<HTMLDivElement>(null);
  const [selection, setSelection] = useState(EMPTY);
  useLayoutEffect(() => {
    const node = root.current;
    if (!node) return;
    let pointer = false,
      previous = "";
    const measure = () => {
      const item = node.querySelector<HTMLElement>(
        '[data-state="on"], [data-state="active"]',
      );
      if (!item) {
        previous = "";
        setSelection((state) =>
          state.visible ? { ...state, visible: false } : state,
        );
        return;
      }
      const a = item.getBoundingClientRect(),
        b = node.getBoundingClientRect();
      const left = a.left - b.left,
        top = a.top - b.top;
      const key = [left, top, a.width, a.height, b.width, b.height].join(",");
      if (key === previous) return;
      previous = key;
      setSelection({
        left,
        top,
        width: a.width,
        height: a.height,
        x: left / Math.max(1, b.width - a.width),
        y: top / Math.max(1, b.height - a.height),
        visible: true,
        pointer,
        boundsWidth: b.width,
        boundsHeight: b.height,
      });
    };
    const onPointer = () => { pointer = true; };
    const onKey = () => { pointer = false; };
    const observer = new MutationObserver((records) => {
      // Dynamic options may reorder/resize; optical filter mutations are not
      // layout changes to the real controls and must not trigger measurement.
      if (records.some(({ target }) => {
        const element = target instanceof Element ? target : target.parentElement;
        return !element?.closest("[data-glass-target-lens]");
      })) measure();
    });
    observer.observe(node, {
      subtree: true,
      attributes: true,
      childList: true,
      characterData: true,
      attributeFilter: ["data-state"],
    });
    const resize = typeof ResizeObserver === "undefined" ? null :
      new ResizeObserver(() => {
        pointer = false;
        measure();
      });
    resize?.observe(node);
    for (const item of node.querySelectorAll<HTMLElement>("[data-state]"))
      resize?.observe(item);
    node.addEventListener("pointerdown", onPointer, true);
    node.addEventListener("keydown", onKey, true);
    measure();
    return () => {
      observer.disconnect();
      resize?.disconnect();
      node.removeEventListener("pointerdown", onPointer, true);
      node.removeEventListener("keydown", onKey, true);
    };
  }, []);

  const indicator = {
    lens: {
      lensW: selection.width,
      lensH: selection.height,
      borderRadius: 999,
    },
    x: selection.x,
    y: selection.y,
    active: selection.visible,
    parameters: CONTROL_LENS_PRESETS.selection,
    duration: selection.pointer ? 500 : 0,
  };
  return (
    <div
      ref={root}
      className="glass-selection-source relative flex min-w-0 flex-1 self-stretch"
    >
      <span
        aria-hidden="true"
        data-selection-fallback=""
        style={{
          position: "absolute",
          pointerEvents: "none",
          left: selection.left,
          top: selection.top,
          width: selection.width,
          height: selection.height,
          borderRadius: 999,
          background: "color-mix(in oklab,var(--foreground) 8%,transparent)",
          opacity: selection.visible ? 1 : 0,
        }}
      />
      {refractionTarget ? (
        <>
          {children}
          <SelectionLens selection={selection} owner={root}>
            {refractionTarget}
          </SelectionLens>
        </>
      ) : (
        <GlassLens {...indicator} className="size-full">
          {children}
        </GlassLens>
      )}
    </div>
  );
}

const subscribeMotion = (callback: () => void) => {
  const media = matchMedia("(prefers-reduced-motion: reduce)");
  media.addEventListener("change", callback);
  return () => media.removeEventListener("change", callback);
};
const reducedMotion = () => matchMedia("(prefers-reduced-motion: reduce)").matches;
const PADDING = 64;
const OPTICS = CONTROL_LENS_PRESETS.selection;
// Selection has its own pacing; the approved slider/switch springs stay intact.
const SELECTION_DURATION = 1200;
const CAP_RELEASE = 205;
const CAP_SETTLE = 180;
type Rect = { left: number; top: number; width: number; height: number };

/** Native controls never resize. Only this small lens changes shape, using
 * exact rounded-rectangle maps instead of stretching an oversized bitmap. */
function SelectionLens({ selection, owner, children }: {
  selection: typeof EMPTY;
  owner: RefObject<HTMLDivElement | null>;
  children: ReactNode;
}) {
  const root = useRef<HTMLDivElement>(null), layer = useRef<HTMLDivElement>(null);
  const housing = useRef<SVGSVGElement>(null), reflection = useRef<HTMLDivElement>(null);
  const target = useRef<HTMLDivElement>(null), manager = useRef<GlassFilterManager | null>(null);
  const pose = useRef<Rect | null>(null), velocity = useRef({ left: 0, top: 0, width: 0, height: 0 });
  const paint = useRef<(rect: Rect) => void>(() => {});
  const settings = useGlassSettings(), solid = useSyncExternalStore(subscribe, reduced, server);
  const still = useSyncExternalStore(subscribeMotion, reducedMotion, server);
  const [admitted, setAdmitted] = useState(false), [ready, setReady] = useState(false);
  const fullWidth = selection.boundsWidth + PADDING * 2,
    fullHeight = selection.boundsHeight + PADDING * 2;
  const bounded = selection.boundsWidth > 0 && selection.boundsHeight > 0 &&
    fullWidth <= 4096 && fullHeight <= 4096 && fullWidth * fullHeight <= 1_500_000;
  useEffect(() => {
    if (!selection.visible || !bounded || solid || !owner.current) return;
    return registerGlassLens(owner.current, setAdmitted, { priority: GLASS_PRIORITY.control, limit: settings.performance?.maxActiveSurfaces });
  }, [selection.visible, bounded, solid, owner, settings.performance?.maxActiveSurfaces]);

  useLayoutEffect(() => {
    if (!admitted || solid || !bounded || !housing.current || !layer.current) return;
    const filter = new GlassFilterManager(housing.current, layer.current);
    manager.current = filter;
    let disposed = false, revision = 0, requestedKey = "", frame = 0;
    let current: { width: number; height: number; pad: number; reflection: string } | null = null;
    const place = () => {
      const rect = pose.current;
      if (!rect || !layer.current || !current || !reflection.current) return;
      const left = PADDING + rect.left + (rect.width - current.width) / 2,
        top = PADDING + rect.top + (rect.height - current.height) / 2;
      // Keep the accepted map, contour and glint together while a new shape
      // decodes. Its center follows input immediately; pixels never stretch.
      layer.current.style.clipPath = `inset(${top}px ${fullWidth - left - current.width}px ${fullHeight - top - current.height}px ${left}px round ${Math.min(current.width, current.height) / 2}px)`;
      filter.moveMap(left - current.pad, top - current.pad, current.width + current.pad * 2, current.height + current.pad * 2);
      Object.assign(reflection.current.style, {
        left: `${left - current.pad}px`, top: `${top - current.pad}px`,
        width: `${current.width + current.pad * 2}px`, height: `${current.height + current.pad * 2}px`,
        backgroundImage: `url("${current.reflection}")`,
      });
      filter.refresh();
      if (root.current) root.current.dataset.glassFilterPaints = String(filter.refreshes);
    };
    paint.current = (rect) => {
      pose.current = rect;
      // Half-pixel geometry bounds the number of maps during a short squish.
      // Pure translation reuses the current PNG and SVG graph.
      const width = Math.max(2, Math.round(rect.width * 2) / 2),
        height = Math.max(2, Math.round(rect.height * 2) / 2), key = `${width},${height}`;
      if (key !== requestedKey) {
        requestedKey = key;
        const request = ++revision, texture = buildControlLensTextures(width, height, height / 2, OPTICS);
        if (!texture.displacement) return;
        const metrics = controlLensMetrics(width, height, OPTICS);
        void decodeLensTextures(texture).then(() => {
          if (disposed || request !== revision) return;
          current = { width, height, pad: metrics.pad, reflection: texture.reflection };
          const rect = pose.current!;
          if (!filter.template) filter.update({
            map: texture.displacement, width: fullWidth, height: fullHeight,
            depth: settings.refraction === false ? 0 : metrics.displacementScale,
            chroma: 0, blur: 0, opticalTransmission: settings.refraction !== false,
            mapRegion: { x: PADDING + rect.left - metrics.pad, y: PADDING + rect.top - metrics.pad,
              width: width + metrics.pad * 2, height: height + metrics.pad * 2 },
          });
          else filter.replaceMap(texture.displacement, settings.refraction === false ? 0 : metrics.displacementScale);
          place();
          setReady(true);
        }).catch(() => { if (!disposed && request === revision) setReady(false); });
      }
      place();
    };
    const refresh = () => {
      if (!frame && !document.hidden) frame = requestAnimationFrame(() => { frame = 0; filter.refresh(); });
    };
    const source = new MutationObserver(refresh);
    if (target.current) source.observe(target.current, { childList: true, subtree: true, characterData: true, attributes: true });
    const theme = new MutationObserver(refresh);
    theme.observe(document.documentElement, { attributes: true, attributeFilter: ["class", "style", "data-theme"] });
    theme.observe(document.body, { attributes: true, attributeFilter: ["class", "style", "data-theme"] });
    document.fonts?.addEventListener("loadingdone", refresh);
    return () => {
      disposed = true;
      cancelAnimationFrame(frame);
      source.disconnect(); theme.disconnect();
      document.fonts?.removeEventListener("loadingdone", refresh);
      paint.current = () => {};
      filter.destroy(); manager.current = null;
      setReady(false);
    };
  }, [admitted, solid, bounded, fullWidth, fullHeight, settings.refraction]);

  useLayoutEffect(() => {
    const to = { left: selection.left, top: selection.top, width: selection.width, height: selection.height };
    const from = pose.current ?? to, momentum = { ...velocity.current };
    const moving = Math.hypot(from.left - to.left, from.top - to.top) > 0.1;
    const duration = selection.pointer && moving && admitted && !still && !solid ? SELECTION_DURATION : 0;
    let frame = 0, lift = 0;
    const start = performance.now();
    let last = start;
    const draw = (now: number) => {
      const elapsed = duration && !document.hidden ? Math.min(duration, now - start) : duration;
      const next = { ...to };
      for (const key of ["left", "top", "width", "height"] as const) {
        const value = sampleControlLensSpring(from[key], to[key], momentum[key], elapsed, duration);
        next[key] = value.value;
        velocity.current[key] = value.velocity;
      }
      const distance = Math.max(0.1, Math.hypot(to.left - from.left, to.top - from.top));
      const arrival = 1 - Math.min(1, Math.hypot(to.left - next.left, to.top - next.top) / distance);
      // Travel opens the cap. A slower release keeps its actual curved shape
      // inspectable as the spring arrives, then closes with a zero-slope finish.
      // There is no opening delay or separate grow-then-slide animation.
      lift = elapsed < duration ? Math.max(Math.sin(Math.PI * arrival), lift * Math.exp(-(now - last) / CAP_RELEASE)) : 0;
      last = now;
      const tail = duration ? Math.max(0, Math.min(1, (duration - elapsed) / CAP_SETTLE)) : 0;
      const expansion = lift * tail * tail * (3 - 2 * tail);
      const width = next.width + expansion * 4, height = Math.min(to.height + 24, next.height + expansion * 24);
      const rect = { left: next.left - expansion * 2, top: next.top - expansion * 12, width, height };
      pose.current = rect;
      paint.current(rect);
      if (elapsed < duration) frame = requestAnimationFrame(draw);
    };
    draw(start);
    return () => cancelAnimationFrame(frame);
  }, [selection, admitted, solid, still, bounded, fullWidth, fullHeight, settings.refraction]);

  const visible = ready && admitted && !solid && selection.visible;
  return (
    <div ref={root} aria-hidden="true" inert data-glass-ignore="" data-glass-target-lens="" data-lens-visible={visible}
      data-glass-rendering={visible ? "active" : "lightweight"}
      data-refraction={visible ? "target-svg" : "disabled"}
      data-glass-fallback={visible ? undefined : solid ? "accessibility-preference" : !selection.visible ? "unselected" : !bounded ? "source-bounds" : !admitted ? "budget" : "textures-pending"}
      style={{ position: "absolute", inset: "-20px -8px", overflow: "clip", zIndex: 2, pointerEvents: "none", opacity: visible ? 1 : 0 }}>
      <div style={{ position: "absolute", left: 8 - PADDING, top: 20 - PADDING, width: fullWidth, height: fullHeight }}>
        <svg ref={housing} width="0" height="0" style={{ position: "absolute" }} />
        <div ref={layer} style={{ position: "absolute", inset: 0, background: "var(--glass-lens-plane,var(--background))" }}>
          <div ref={target} style={{ position: "absolute", inset: PADDING }}>{children}</div>
        </div>
        <div ref={reflection} style={{ position: "absolute", backgroundSize: "100% 100%" }} />
      </div>
    </div>
  );
}
